OTHER_TEXT = "Not on the list? Tell us what you need. We check it, send you the price, and you decide."


def add_other_services(connection):
    shops = sa.table("shops", sa.column("id"))
    bay_types = sa.table("bay_types", sa.column("id"), sa.column("shop_id"), sa.column("vehicle_kind"))
    services = sa.table("services", sa.column("shop_id"), sa.column("name"), sa.column("category"),
                        sa.column("description"), sa.column("vehicle_kind"), sa.column("work_minutes"),
                        sa.column("buffer_minutes"), sa.column("bay_type_id"), sa.column("price_from"),
                        sa.column("position"), sa.column("is_active"), sa.column("again_months"),
                        sa.column("again_km"), sa.column("is_other"))
    for (shop_id,) in connection.execute(sa.select(shops.c.id)).all():
        for kind, name in (("car", "Other Car Service"), ("moto", "Other Motorcycle Service")):
            bay_type = connection.execute(
                sa.select(bay_types.c.id).where(bay_types.c.shop_id == shop_id,
                                                bay_types.c.vehicle_kind.in_((kind, "any")))
                .order_by(bay_types.c.id).limit(1)).scalar()
            taken = connection.execute(sa.select(sa.func.count()).select_from(services).where(
                services.c.shop_id == shop_id, services.c.name == name)).scalar()
            if bay_type is None or taken:
                continue  # no bay for it yet (the owner can add one in Settings), or the name is in use
            connection.execute(services.insert().values(
                shop_id=shop_id, name=name, category="Other", description=OTHER_TEXT, vehicle_kind=kind,
                work_minutes=60, buffer_minutes=0, bay_type_id=bay_type, price_from=0, position=999,
                is_active=True, again_months=0, again_km=0, is_other=True))


